retrieval.cypher:
MATCH (p:PlantItem {tag: 'P-3701C'}), (e:PlantItem {tag: 'E-3901'})
CALL {
  WITH p
  MATCH (p)-[:line_to*1..]->(v:Valve)
  RETURN collect(DISTINCT v) AS downstream_valves
}
CALL {
  WITH e
  MATCH (v:Valve)-[:line_to*1..]->(e)
  RETURN collect(DISTINCT v) AS upstream_valves
}
WITH [v IN downstream_valves WHERE v IN upstream_valves | v.tag] AS valve_tags
RETURN size(valve_tags) AS valve_count, valve_tags AS valve_tags

